import React from 'react';
import StatCard from './StatCard';
import RevenueChart from './RevenueChart';

interface StatData {
  label: string;
  value: number;
  change: number; // positive for increase, negative for decrease
  trend: 'up' | 'down';
}

interface ChartData {
  month: string;
  revenue: number;
}

const App: React.FC = () => {
  const statData: StatData[] = [
    { label: 'Revenue', value: 125000, change: 12, trend: 'up' },
    { label: 'Users', value: 23400, change: 8, trend: 'up' },
    { label: 'Orders', value: 4560, change: 15, trend: 'up' },
    { label: 'Churn', value: 120, change: -3, trend: 'down' },
  ];

  const chartData: ChartData[] = [
    { month: 'Jan', revenue: 8000 },
    { month: 'Feb', revenue: 9500 },
    { month: 'Mar', revenue: 10500 },
    { month: 'Apr', revenue: 11000 },
    { month: 'May', revenue: 12000 },
    { month: 'Jun', revenue: 13500 },
    { month: 'Jul', revenue: 14500 },
    { month: 'Aug', revenue: 15000 },
    { month: 'Sep', revenue: 16000 },
    { month: 'Oct', revenue: 17000 },
    { month: 'Nov', revenue: 18000 },
    { month: 'Dec', revenue: 19500 },
  ];

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-2xl font-bold text-gray-900 mb-6">Dashboard</h1>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          {statData.map((stat, index) => (
            <StatCard key={index} stat={stat} />
          ))}
        </div>

        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">Monthly Revenue</h2>
          <RevenueChart data={chartData} />
        </div>
      </div>
    </div>
  );
};

export { App };
```

