### StatCard.tsx
```tsx
import React from 'react';
import { ArrowUpIcon, ArrowDownIcon } from 'lucide-react';

interface StatCardProps {
  stat: {
    label: string;
    value: number;
    change: number;
    trend: 'up' | 'down';
  };
}

const StatCard: React.FC<StatCardProps> = ({ stat }) => {
  const TrendIcon = stat.trend === 'up' ? ArrowUpIcon : ArrowDownIcon;

  return (
    <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 transition-all duration-200 hover:shadow-md">
      <div className="flex justify-between items-start mb-2">
        <h3 className="text-sm font-medium text-gray-500">{stat.label}</h3>
        <div className="flex items-center text-sm">
          <TrendIcon className={`h-4 w-4 ${stat.trend === 'up' ? 'text-green-500' : 'text-red-500'}`} />
          <span className={`ml-1 font-medium ${stat.trend === 'up' ? 'text-green-600' : 'text-red-600'}`}>
            {stat.change > 0 ? '+' : ''}{stat.change}%
          </span>
        </div>
      </div>
      <div className="text-2xl font-bold text-gray-900">{stat.value.toLocaleString()}</div>
    </div>
  );
};

export { StatCard };
```

### RevenueChart.tsx
```tsx
import React from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

interface ChartData {
  month: string;
  revenue: number;
}

interface RevenueChartProps {
  data: ChartData[];
}

const RevenueChart: React.FC<RevenueChartProps> = ({ data }) => {
  return (
    <div className="h-64">
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={data}>
          <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
          <XAxis dataKey="month" tickLine={false} axisLine={false} tick={{ fontSize: 12 }} />
          <YAxis tickLine={false} axisLine={false} tick={{ fontSize: 12 }} />
          <Tooltip
            formatter={(value) => `${value.toLocaleString()} USD`}
            itemStyle={{ fontSize: 12 }}
          />
          <Legend verticalAlign="top" height={36} />
          <Line
            type="monotone"
            dataKey="revenue"
            stroke="#047857"
            strokeWidth={3}
            activeDot={{ r: 6 }}
            dot={{ r: 6 }}
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
};

export { RevenueChart };
```

